import Navigation from "./Navigation";
import data from "../data";

function Header(){
	return(
		<header>
			<div className="hd_inr">
				<Logo />
				<Navigation />
				<div className="sub_bg"></div>
				<div className="mobile">
					<a href="">
						<span>1</span>
						<span>2</span>
					</a>
				</div>
			</div>
		</header>
	)
}

function Logo(){
	return(
		<div className="logo">
			<a href=""><img src="/images/logo.png" alt="logo"/></a>
		</div>
	)
}

export default Header;
